import { NeuralWeights, HardwareConfig } from '../types';

export function generateArduinoCode(weights: NeuralWeights | null, config: HardwareConfig): string {
  const { boardType } = config;
  
  const isESP32 = boardType === 'esp32';
  const sensorCount = 8;
  const motorCount = 4;

  let code = `/*
 * Sesame Robot - AI Control Firmware
 * Generated by Sesame Robot AI Training Lab
 * Board: ${boardType.toUpperCase()}
 * 
 * This code implements a neural network controller for obstacle avoidance
 * and autonomous navigation. Upload this to your ${boardType} via Arduino IDE.
 */

`;

  // Board-specific includes
  if (isESP32) {
    code += `#include <WiFi.h>
#include <WebSocketsServer.h>
#include <ArduinoJson.h>

// WiFi Configuration
const char* WIFI_SSID = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";

WebSocketsServer webSocket = WebSocketsServer(81);

`;
  } else {
    code += `#include <Arduino.h>
`;
  }

  // Motor driver pins (L298N or similar)
  code += `// Motor pins (L298N driver)
const int MOTOR_A_ENA = ${isESP32 ? '14' : '5'};
const int MOTOR_A_IN1 = ${isESP32 ? '27' : '6'};
const int MOTOR_A_IN2 = ${isESP32 ? '26' : '7'};
const int MOTOR_B_ENB = ${isESP32 ? '12' : '10'};
const int MOTOR_B_IN3 = ${isESP32 ? '25' : '8'};
const int MOTOR_B_IN4 = ${isESP32 ? '33' : '9'};

// Ultrasonic sensor pins (HC-SR04)
`;

  // Sensor pins
  const sensorPins = isESP32 
    ? [32, 35, 34, 39, 36, 13, 16, 17]
    : [2, 3, 4, 7, 8, 11, 12, 13];
  
  code += `const int SENSOR_TRIG_PINS[] = {${sensorPins.join(', ')}};\n`;
  code += `const int SENSOR_ECHO_PINS[] = {${isESP32 ? '18, 19, 21, 22, 23, 4, 15, 2' : 'A0, A1, A2, A3, A4, A5, A6, A7'}};\n\n`;

  // IMU pins (MPU6050)
  code += `// IMU (MPU6050 via I2C)
#include <Wire.h>
const int MPU_ADDR = 0x68;

// Battery monitoring
const int BATTERY_PIN = ${isESP32 ? '35' : 'A0'};

// Neural Network Parameters
`;

  // Neural network weights
  if (weights) {
    code += `const int INPUT_SIZE = ${weights.inputWeights[0].length};
const int HIDDEN_SIZE = ${weights.inputWeights.length};
const int OUTPUT_SIZE = ${weights.hiddenWeights.length};

// Input layer weights
const float inputWeights[HIDDEN_SIZE][INPUT_SIZE] = {
`;
    for (let i = 0; i < weights.inputWeights.length; i++) {
      code += `  {${weights.inputWeights[i].map(w => w.toFixed(4)).join(', ')}}`;
      if (i < weights.inputWeights.length - 1) code += ',';
      code += '\n';
    }
    code += `};

const float inputBiases[HIDDEN_SIZE] = {${weights.inputBiases.map(b => b.toFixed(4)).join(', ')}};

// Hidden layer weights
const float hiddenWeights[OUTPUT_SIZE][HIDDEN_SIZE] = {
`;
    for (let i = 0; i < weights.hiddenWeights.length; i++) {
      code += `  {${weights.hiddenWeights[i].map(w => w.toFixed(4)).join(', ')}}`;
      if (i < weights.hiddenWeights.length - 1) code += ',';
      code += '\n';
    }
    code += `};

const float hiddenBiases[OUTPUT_SIZE] = {${weights.hiddenBiases.map(b => b.toFixed(4)).join(', ')}};

`;
  } else {
    code += `const int INPUT_SIZE = 10;
const int HIDDEN_SIZE = 12;
const int OUTPUT_SIZE = 3;

// Placeholder weights - will be overwritten by upload
float inputWeights[HIDDEN_SIZE][INPUT_SIZE];
float inputBiases[HIDDEN_SIZE];
float hiddenWeights[OUTPUT_SIZE][HIDDEN_SIZE];
float hiddenBiases[OUTPUT_SIZE];

`;
  }

  // Variables
  code += `// Global variables
float sensorDistances[${sensorCount}];
float motorSpeeds[${motorCount}];
float batteryLevel = 100.0;
float imuRoll = 0, imuPitch = 0, imuYaw = 0;
unsigned long lastSensorRead = 0;
unsigned long lastTelemetrySend = 0;
const int SENSOR_READ_INTERVAL = 50;  // ms
const int TELEMETRY_SEND_INTERVAL = 200;  // ms

// Neural network functions
float sigmoid(float x) {
  return 1.0 / (1.0 + exp(-x));
}

void forwardPass(float inputs[], float outputs[]) {
  // Hidden layer
  float hidden[HIDDEN_SIZE];
  for (int i = 0; i < HIDDEN_SIZE; i++) {
    float sum = inputBiases[i];
    for (int j = 0; j < INPUT_SIZE; j++) {
      sum += inputs[j] * inputWeights[i][j];
    }
    hidden[i] = sigmoid(sum);
  }
  
  // Output layer
  for (int i = 0; i < OUTPUT_SIZE; i++) {
    float sum = hiddenBiases[i];
    for (int j = 0; j < HIDDEN_SIZE; j++) {
      sum += hidden[j] * hiddenWeights[i][j];
    }
    outputs[i] = sigmoid(sum);
  }
}

// Sensor reading functions
float readUltrasonic(int trigPin, int echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  
  long duration = pulseIn(echoPin, HIGH, 30000);  // 30ms timeout
  float distance = duration * 0.034 / 2.0;  // cm
  
  if (distance == 0 || distance > 200) distance = 200;
  return distance;
}

void readAllSensors() {
  for (int i = 0; i < ${sensorCount}; i++) {
    sensorDistances[i] = readUltrasonic(SENSOR_TRIG_PINS[i], SENSOR_ECHO_PINS[i]);
  }
}

// Motor control
void setMotorSpeed(int motor, int speed) {
  speed = constrain(speed, -255, 255);
  
  if (motor == 0) {
    if (speed >= 0) {
      digitalWrite(MOTOR_A_IN1, HIGH);
      digitalWrite(MOTOR_A_IN2, LOW);
    } else {
      digitalWrite(MOTOR_A_IN1, LOW);
      digitalWrite(MOTOR_A_IN2, HIGH);
    }
    analogWrite(MOTOR_A_ENA, abs(speed));
  } else if (motor == 1) {
    if (speed >= 0) {
      digitalWrite(MOTOR_B_IN3, HIGH);
      digitalWrite(MOTOR_B_IN4, LOW);
    } else {
      digitalWrite(MOTOR_B_IN3, LOW);
      digitalWrite(MOTOR_B_IN4, HIGH);
    }
    analogWrite(MOTOR_B_ENB, abs(speed));
  }
}

void applyMotorCommands(float speed, float turn, float brake) {
  // Differential drive
  float leftSpeed = (speed + turn) * 255 * (1.0 - brake * 0.5);
  float rightSpeed = (speed - turn) * 255 * (1.0 - brake * 0.5);
  
  setMotorSpeed(0, leftSpeed);
  setMotorSpeed(1, rightSpeed);
  
  motorSpeeds[0] = leftSpeed;
  motorSpeeds[1] = rightSpeed;
}

// IMU reading
void readIMU() {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x3B);  // Starting with register 0x3B (ACCEL_XOUT_H)
  Wire.endTransmission(false);
  Wire.requestFrom(MPU_ADDR, 6, true);
  
  int16_t AcX = Wire.read() << 8 | Wire.read();
  int16_t AcY = Wire.read() << 8 | Wire.read();
  int16_t AcZ = Wire.read() << 8 | Wire.read();
  
  imuRoll = atan2(AcY, AcZ) * 180.0 / M_PI;
  imuPitch = atan2(-AcX, sqrt(AcY * AcY + AcZ * AcZ)) * 180.0 / M_PI;
}

// Battery reading
void readBattery() {
  int raw = analogRead(BATTERY_PIN);
  batteryLevel = map(raw, 0, ${isESP32 ? '4095' : '1023'}, 0, 100);
}

`;

  // WiFi/WebSocket functions for ESP32
  if (isESP32) {
    code += `// WebSocket event handler
void webSocketEvent(uint8_t num, WStype_t type, uint8_t * payload, size_t length) {
  switch(type) {
    case WStype_CONNECTED:
      Serial.printf("WebSocket client #%u connected\\n", num);
      break;
    case WStype_DISCONNECTED:
      Serial.printf("WebSocket client #%u disconnected\\n", num);
      break;
    case WStype_TEXT:
      handleCommand(String((char *)payload));
      break;
  }
}

void handleCommand(String cmd) {
  if (cmd.startsWith("M:")) {
    // Motor command: M:left,right
    String values = cmd.substring(2);
    int commaIdx = values.indexOf(',');
    if (commaIdx > 0) {
      float left = values.substring(0, commaIdx).toFloat();
      float right = values.substring(commaIdx + 1).toFloat();
      setMotorSpeed(0, left * 255);
      setMotorSpeed(1, right * 255);
    }
  } else if (cmd.startsWith("W:")) {
    // Weight upload: W:{json}
    String json = cmd.substring(2);
    // Parse and update weights (simplified)
    Serial.println("STATUS:Weights received");
  } else if (cmd.startsWith("STATUS")) {
    // Status request
    sendTelemetry();
  }
}

void sendTelemetry() {
  StaticJsonDocument<512> doc;
  doc["type"] = "telemetry";
  doc["timestamp"] = millis();
  
  JsonArray sensors = doc.createNestedArray("sensors");
  for (int i = 0; i < ${sensorCount}; i++) {
    sensors.add(sensorDistances[i]);
  }
  
  JsonArray motors = doc.createNestedArray("motors");
  for (int i = 0; i < ${motorCount}; i++) {
    motors.add(motorSpeeds[i]);
  }
  
  JsonObject imu = doc.createNestedObject("imu");
  imu["roll"] = imuRoll;
  imu["pitch"] = imuPitch;
  imu["yaw"] = imuYaw;
  
  doc["battery"] = batteryLevel;
  
  String output;
  serializeJson(doc, output);
  webSocket.broadcastTXT(output);
}

void setupWiFi() {
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  Serial.print("Connecting to WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Connected! IP: ");
  Serial.println(WiFi.localIP());
  
  webSocket.begin();
  webSocket.onEvent(webSocketEvent);
}

`;
  }

  // Setup function
  code += `void setup() {
  Serial.begin(${config.baudRate});
  Serial.println("STATUS:Sesame Robot Starting...");
  
  // Initialize pins
  pinMode(MOTOR_A_ENA, OUTPUT);
  pinMode(MOTOR_A_IN1, OUTPUT);
  pinMode(MOTOR_A_IN2, OUTPUT);
  pinMode(MOTOR_B_ENB, OUTPUT);
  pinMode(MOTOR_B_IN3, OUTPUT);
  pinMode(MOTOR_B_IN4, OUTPUT);
  
  for (int i = 0; i < ${sensorCount}; i++) {
    pinMode(SENSOR_TRIG_PINS[i], OUTPUT);
    pinMode(SENSOR_ECHO_PINS[i], INPUT);
  }
  
  // Initialize I2C for IMU
  Wire.begin();
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x6B);  // PWR_MGMT_1 register
  Wire.write(0);     // Set to zero (wake up the MPU-6050)
  Wire.endTransmission(true);
  
`;

  if (isESP32) {
    code += `  // Initialize WiFi
  setupWiFi();
  
`;
  }

  code += `  Serial.println("STATUS:Initialization complete");
  Serial.println("STATUS:Ready for commands");
}

// Main loop
void loop() {
  unsigned long currentTime = millis();
  
  // Read sensors periodically
  if (currentTime - lastSensorRead >= SENSOR_READ_INTERVAL) {
    readAllSensors();
    readIMU();
    readBattery();
    lastSensorRead = currentTime;
    
    // Prepare neural network inputs
    float inputs[INPUT_SIZE];
    for (int i = 0; i < ${sensorCount}; i++) {
      inputs[i] = sensorDistances[i] / 200.0;  // Normalize to 0-1
    }
    inputs[8] = 0.5;  // Placeholder for target direction
    inputs[9] = 0.5;  // Placeholder for target distance
    
    // Run neural network
    float outputs[OUTPUT_SIZE];
    forwardPass(inputs, outputs);
    
    // Apply motor commands
    applyMotorCommands(outputs[0], outputs[1] - 0.5, outputs[2]);
  }
  
  // Send telemetry periodically
  if (currentTime - lastTelemetrySend >= TELEMETRY_SEND_INTERVAL) {
`;

  if (isESP32) {
    code += `    sendTelemetry();
`;
  } else {
    code += `    // Send sensor data via serial
    Serial.print("S:");
    for (int i = 0; i < ${sensorCount}; i++) {
      Serial.print(sensorDistances[i]);
      if (i < ${sensorCount} - 1) Serial.print(",");
    }
    Serial.println();
    
    // Send telemetry
    Serial.print("T:");
    Serial.print(batteryLevel);
    Serial.print(",");
    Serial.print(imuRoll);
    Serial.print(",");
    Serial.print(imuPitch);
    Serial.print(",");
    Serial.println(imuYaw);
`;
  }

  code += `    lastTelemetrySend = currentTime;
  }
  
  // Handle serial commands
  if (Serial.available()) {
    String cmd = Serial.readStringUntil('\\n');
    cmd.trim();
    
    if (cmd.startsWith("M:")) {
      // Motor command
      String values = cmd.substring(2);
      int commaIdx = values.indexOf(',');
      if (commaIdx > 0) {
        float left = values.substring(0, commaIdx).toFloat();
        float right = values.substring(commaIdx + 1).toFloat();
        setMotorSpeed(0, left * 255);
        setMotorSpeed(1, right * 255);
      }
    } else if (cmd.startsWith("W:")) {
      // Weight upload
      Serial.println("STATUS:Weights received");
    }
  }
  
${isESP32 ? '  webSocket.loop();' : '  delay(1);'}
}
`;

  return code;
}

export function generatePlatformIOConfig(config: HardwareConfig): string {
  const boardMap = {
    esp32: 'esp32dev',
    arduino_uno: 'uno',
    arduino_mega: 'megaatmega2560',
    arduino_nano: 'nanoatmega328',
  };

  return `; PlatformIO Configuration for Sesame Robot
; Generated by Sesame Robot AI Training Lab

[env:${config.boardType}]
platform = ${config.boardType === 'esp32' ? 'espressif32' : 'atmelavr'}
board = ${boardMap[config.boardType]}
framework = arduino
monitor_speed = ${config.baudRate}
lib_deps = 
${config.boardType === 'esp32' ? `    links2004/WebSockets @ ^2.4.0
    bblanchon/ArduinoJson @ ^6.21.0` : ''}
    Wire
`;
}
